package com.lendup.reservas.infrastructure.messaging;
import com.lendup.reservas.application.exception.NotFoundException; import com.lendup.reservas.application.port.out.*; import com.lendup.reservas.config.RabbitConfiguration; import com.lendup.reservas.domain.event.EventEnvelope; import com.lendup.reservas.infrastructure.persistence.entity.*; import com.lendup.reservas.infrastructure.persistence.repository.ProcessedEventJpaRepository; import java.time.*; import java.util.*; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import tools.jackson.core.type.TypeReference; import tools.jackson.databind.json.JsonMapper;
@Component public class LoanEventConsumer { private final JsonMapper json; private final ReservationPersistencePort persistence; private final ProcessedEventJpaRepository processed; private final OutboxPort outbox; private final AuditPort audit; private final Clock clock; public LoanEventConsumer(JsonMapper j,ReservationPersistencePort p,ProcessedEventJpaRepository x,OutboxPort o,AuditPort a,Clock c){json=j;persistence=p;processed=x;outbox=o;audit=a;clock=c;}
  @RabbitListener(queues=RabbitConfiguration.LOAN_QUEUE) @Transactional public void consume(byte[] body)throws Exception{Map<String,Object> e=json.readValue(body,new TypeReference<Map<String,Object>>(){});UUID eventId=UUID.fromString(e.get("event_id").toString());if(processed.existsById(eventId))return;String type=e.get("event_type").toString();long version=((Number)e.getOrDefault("aggregate_version",0)).longValue();@SuppressWarnings("unchecked") Map<String,Object> payload=(Map<String,Object>)e.get("payload");UUID reservationId=UUID.fromString(payload.get("reserva_id").toString());ReservaEntity reservation=persistence.lockReserva(reservationId).orElseThrow(()->new NotFoundException("Reserva de evento no encontrada"));String previous=reservation.getEstado().name();boolean changed=switch(type){case "PrestamoCancelado"->reservation.aplicarPrestamoCancelado(version,clock.instant());case "CancelacionRechazada"->reservation.aplicarCancelacionRechazada(version,clock.instant());case "PeriodoPrestamoLiberado"->reservation.aplicarLiberacion(version,LocalDateTime.parse(payload.get("nuevo_hasta").toString()),clock.instant());default->throw new IllegalArgumentException("Tipo de evento no soportado: "+type);};if(changed){persistence.saveReserva(reservation);audit.record("RESERVA",reservationId,"APLICAR_"+type,previous,reservation.getEstado().name(),null,e.getOrDefault("correlation_id","").toString());if(type.equals("PrestamoCancelado")){outbox.append(new EventEnvelope(UUID.randomUUID(),"ReservaCancelada",1,version,reservationId,clock.instant(),e.getOrDefault("correlation_id","").toString(),Map.of("reserva_id",reservationId,"solicitud_id",reservation.getSolicitud().getId())));}}processed.save(new ProcessedEventEntity(eventId,"reservations.loan-events.v1",reservationId,version,clock.instant()));}
}
